We assume that we are given a $p\times n$ matrix $\mathbf Y$ generated by the following model:
\begin{equation}\label{model1}
	\mathbf Y = \mathbf\Theta+\sigma\boldsymbol\Xi, \quad \xi_{i,j} \overset{\text{iid}}{\sim} \mathcal{N}(0,1).
\end{equation}

\begin{equation}\label{model1}
	\mathbf Y = \mathbf\Theta+\sigma\boldsymbol\Xi, \quad \xi_{i,j} \overset{\text{iid}}{\sim} \mathcal{N}(0,1).
\end{equation}

Equivalently, the columns $\boldsymbol Y\!_i$ of $\mathbf Y$ satisfy
\begin{equation}
	\boldsymbol Y\!_i = \boldsymbol\theta_i+\sigma\boldsymbol\xi_i, \quad \boldsymbol\xi_i \overset{\text{iid}}{\sim} \mathcal{N}(\mathbf 0_p,\mathbf I_p),\quad i=1,\ldots,n.
\end{equation}

\begin{equation}
	\boldsymbol Y\!_i = \boldsymbol\theta_i+\sigma\boldsymbol\xi_i, \quad \boldsymbol\xi_i \overset{\text{iid}}{\sim} \mathcal{N}(\mathbf 0_p,\mathbf I_p),\quad i=1,\ldots,n.
\end{equation}

Our goal is to estimate the vector $\boldsymbol L(\mathbf\Theta)\in\mathbb R^p$, where $\boldsymbol L:\mathbb R^{p\times n}\to\mathbb R^p$ is the
linear transformation defined by
\begin{equation}\label{L}
	\boldsymbol L(\mathbf\Theta) = \sum_{i=1}^n \boldsymbol\theta_{i} = \mathbf\Theta\bf1_n.
\end{equation}

\begin{equation}\label{L}
	\boldsymbol L(\mathbf\Theta) = \sum_{i=1}^n \boldsymbol\theta_{i} = \mathbf\Theta\bf1_n.
\end{equation}

\begin{equation}\label{risk1}
	\mathbf E_\mathbf\Theta \|\widehat\boldsymbol L-\boldsymbol L(\mathbf\Theta)\|_2^2 = \sigma^2 np.
\end{equation}

In what follows, we denote by $\mathcal M(p,n,s)$ the set of all $p\times n$ matrices with real entries having at most $s$ nonzero columns:
\begin{equation}\label{calM}
\mathcal M(p,n,s) = \Big\{\mathbf\Theta\in \mathbb R^{p\times n} : \sum_{i=1}^n \mathds 1(\|\boldsymbol\theta_i\|_2>0) \le s\Big\}.
\end{equation}

\begin{equation}\label{calM}
\mathcal M(p,n,s) = \Big\{\mathbf\Theta\in \mathbb R^{p\times n} : \sum_{i=1}^n \mathds 1(\|\boldsymbol\theta_i\|_2>0) \le s\Big\}.
\end{equation}

Then we set
\begin{equation}\label{est:greedy}
\widehat S = \widehat J_1\cup \ldots\cup \widehat J_\ell
\quad\text{and}\quad \widehat\boldsymbol L{}^{\rm GSS} = \boldsymbol L(\mathbf Y_{\widehat S}).
\end{equation}

\begin{equation}\label{est:greedy}
\widehat S = \widehat J_1\cup \ldots\cup \widehat J_\ell
\quad\text{and}\quad \widehat\boldsymbol L{}^{\rm GSS} = \boldsymbol L(\mathbf Y_{\widehat S}).
\end{equation}

