	\end{equation}

\label{theorem_HT_lowerbound}
Let us denote by $\widehat{\boldsymbol L}{}^{\rm GHT}_\lambda$ the estimator defined in~\eqref{definition_LHT} with a threshold $\lambda>0$. There are two universal constants $p_0\in\mathbb N$ and $c>0$, such that for any $p\ge p_0$ and $s\le n/61$, the following lower bound holds
	\begin{equation}
		\inf_{\lambda>0}\sup_{\mathbf\Theta\in\mathcal M(p,n,s)} \mathbf E_\mathbf\Theta \big\| \widehat{\boldsymbol L}{}^{\rm GHT}_\lambda-\boldsymbol L(\mathbf\Theta) \big\|_2^2 \ge c\sigma^2\Big((s^2p^{1/2})\wedge (np)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

\begin{equation}
		\inf_{\lambda>0}\sup_{\mathbf\Theta\in\mathcal M(p,n,s)} \mathbf E_\mathbf\Theta \big\| \widehat{\boldsymbol L}{}^{\rm GHT}_\lambda-\boldsymbol L(\mathbf\Theta) \big\|_2^2 \ge c\sigma^2\Big((s^2p^{1/2})\wedge (np)+s^2\log(1+n/s^2)+sp\Big).
	\end{equation}

\label{theorem_BT}
	Let $\widehat{\boldsymbol L}{}^{\rm HT}$ be the element-wise hard thresholding estimator
	defined by $\widehat{\boldsymbol L}{}^{\rm HT}_i = \sum_{j=1}^n \boldsymbol Y\!_{i,j} \mathds{1}_{\boldsymbol Y\!_{i,j}>\lambda}$
	for $i\in [p]$. If the threshold $\lambda$  is chosen so that $\lambda^2=2\sigma^2\log(1+n/s^2)$, then
	\begin{equation}
		\sup_{\mathbf\Theta\in\mathcal M(p,n,s)}\mathbf E_\mathbf\Theta\big[\|\widehat{\boldsymbol L}{}^{\rm HT}-\boldsymbol L(\mathbf\Theta)\|^2 \big]
		\le c\sigma^2s^2p\log(1+n/s^2),
	\end{equation}
	where $c>0$ is a universal constant.

\begin{equation}
