		\le c\sigma^2s^2p\log(1+n/s^2),
	\end{equation}

\begin{equation}\label{definition_ST}
	\widehat{\mathbf\Theta}^{\rm GST} = \arg\min_{\mathbf{T}}
	\Big\{ \sum_{i=1}^n \| \boldsymbol Y\!_i - \boldsymbol{t}_i \|_2^2 + \sum_{i=1}^n \lambda_i \|\boldsymbol{t}_i\|_2 \Big\}.
\end{equation}

\begin{equation}\label{definition_STexplicite}
	\widehat{\boldsymbol\theta}{}^{\,\rm GST}_i = \Big(1-\frac{\lambda_i}{2\|\boldsymbol Y\!_i\|_2}\Big)_+ \boldsymbol Y\!_i.
\end{equation}

\label{theorem_ST}
	The estimator $\widehat{\boldsymbol L}{}^{\rm GST}=\boldsymbol L(\widehat{\mathbf\Theta}^{\rm GST})$ defined
