\begin{equation}\label{definition_observation}
\boldsymbol Y\!_i = \boldsymbol\mu +\boldsymbol\theta_i+\sigma\boldsymbol\xi_i, \quad \boldsymbol\xi_i\overset{\text{iid}}{\sim} \mathcal{N}(\mathbf 0,\mathbf I_p),
\end{equation}
where $\mathbf I_p$ is the identity matrix of dimension $p\times p$.

\begin{equation}\label{definition_observation}
\boldsymbol Y\!_i = \boldsymbol\mu +\boldsymbol\theta_i+\sigma\boldsymbol\xi_i, \quad \boldsymbol\xi_i\overset{\text{iid}}{\sim} \mathcal{N}(\mathbf 0,\mathbf I_p),
\end{equation}

\begin{equation}\label{definition_observation1}
\mathbf Y = \boldsymbol\mu\mathbf 1_n^\top +\boldsymbol\Theta+\sigma\boldsymbol\Xi.
\end{equation}

The problem of estimating the linear functional $\boldsymbol L_n(\boldsymbol\Theta) = (\nicefrac1n)\sum_{i\in[n]}
\boldsymbol\theta_i$ in model \eqref{definition_observation1} is not easier, in the minimax sense, than that of estimating $\boldsymbol\mu$. More precisely, we have
\begin{align}
\frac{\sigma^2 p}{n}\le \inf_{\widehat\boldsymbol\mu}\sup_{\boldsymbol\mu,\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol\mu-\boldsymbol\mu\|_2^2]\le
2\inf_{\widehat\boldsymbol L_n}\sup_{\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol L_n-\boldsymbol L_n(\boldsymbol\Theta)\|_2^2]
+\frac{2\sigma^2 p}{n},
\end{align}
where the sup in the left-hand side and in the right-hand side are taken,
respectively, over all $\boldsymbol\Theta\in\mathcal M(p,n,s)$ and over all $(\boldsymbol\mu,\boldsymbol\Theta)\in
\mathbb R^p\times\mathcal M(p,n,s)$.

\begin{align}
\frac{\sigma^2 p}{n}\le \inf_{\widehat\boldsymbol\mu}\sup_{\boldsymbol\mu,\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol\mu-\boldsymbol\mu\|_2^2]\le
2\inf_{\widehat\boldsymbol L_n}\sup_{\boldsymbol\Theta} \mathbf E[\|\widehat\boldsymbol L_n-\boldsymbol L_n(\boldsymbol\Theta)\|_2^2]
+\frac{2\sigma^2 p}{n},
\end{align}

\begin{align}
\mathbf E[\|\widehat\boldsymbol\mu(\widehat\boldsymbol L_n)-\boldsymbol\mu\|_2^2]
		&= \mathbf E[\|\boldsymbol L_n(\mathbf Y)-\widehat\boldsymbol L_n-n\boldsymbol\mu\|_2^2]\\
		&=\mathbf E[\|\boldsymbol L_n(\boldsymbol\Theta)+\sigma\boldsymbol L_n(\boldsymbol\Xi)-\widehat\boldsymbol L_n\|_2^2]\\
		&\le 2\mathbf E[\|\boldsymbol L_n(\boldsymbol\Theta)-\widehat\boldsymbol L_n\|_2^2] + {2\sigma^2}\mathbf E[\|\boldsymbol L_n(\boldsymbol\Xi)\|_2^2].
\end{align}

Let $\widehat\boldsymbol\mu:\mathbb R^{p\times n}\to\mathbb R^p$ be an estimator of $\boldsymbol\mu$ that can be applied
both to the data matrix $\mathbf X = [\boldsymbol X_1,\ldots,\boldsymbol X_n]$ from Huber's model and to $\mathbf Y$ 
from our model \eqref{definition_observation}. Then, we have
\begin{align}
\underbrace{\sup_{\mathbf Q}\mathbf E_{\boldsymbol\mu,\mathbf Q}[\|\widehat\boldsymbol\mu(\mathbf X)-\boldsymbol\mu\|_2^2]}
_{\text{\rm risk in the Huber model}}\le
\mathbf E_{\widehat s\sim \mathcal B(n,s/n)}
\bigg[\underbrace{\sup_{\boldsymbol\Theta\in\mathcal M(n,p,\widehat s)}
\mathbf E_{\boldsymbol\mu,\boldsymbol\Theta}\big[\|\widehat\boldsymbol\mu(\mathbf Y)-\boldsymbol\mu\|_2^2\big]
}_{\text{\rm risk in our model \eqref{definition_observation}}}\bigg].
\end{align}
The supremum of the left-hand side is over all probability distributions $\mathbf Q$ on $\mathbb R^p$
such that\footnote{We denote by $*$ the convolution of the distributions.} 
$\mathbf Q = \mathbf Q_0 * \mathcal N_p(\mathbf 0, \sigma^2\mathbf I_p)$, 
while the notation $\mathcal B(n,s/n)$ stands for the binomial distribution.

\begin{align}
\underbrace{\sup_{\mathbf Q}\mathbf E_{\boldsymbol\mu,\mathbf Q}[\|\widehat\boldsymbol\mu(\mathbf X)-\boldsymbol\mu\|_2^2]}
_{\text{\rm risk in the Huber model}}\le
\mathbf E_{\widehat s\sim \mathcal B(n,s/n)}
\bigg[\underbrace{\sup_{\boldsymbol\Theta\in\mathcal M(n,p,\widehat s)}
\mathbf E_{\boldsymbol\mu,\boldsymbol\Theta}\big[\|\widehat\boldsymbol\mu(\mathbf Y)-\boldsymbol\mu\|_2^2\big]
}_{\text{\rm risk in our model \eqref{definition_observation}}}\bigg].
\end{align}

On the other side,
it has been established in \citep{Gao2015} that the minimax rate of estimating
