\label{lemme_chideux}
	If $\eta$ is a random variable drawn from the $\chi^2_d$ distribution, then for every $x>0$
	\begin{equation}
		\mathbf P\big(\eta \ge d+ x\big) \le e^{-\frac1{16d} x (x\wedge 4d)} .
	\end{equation}

\begin{equation}
		\mathbf P\big(\eta \ge d+ x\big) \le e^{-\frac1{16d} x (x\wedge 4d)} .
	\end{equation}

\label{lemme_esperancechideux}
	If $\eta$ is a random variable drawn from the $\chi^2_d$ distribution, then for every $x>0$ and $d\ge 2$,
	\begin{equation}
	\mathbf E\big(\eta \mathds{1}_{\eta\ge d+x}\big) \le 2d\,e^{-x^2/32d} \,\mathds{1}_{x< 4d} +
	2xe^{-x/4} \mathds{1}_{x\ge 4d}.
	\end{equation}

\begin{equation}
	\mathbf E\big(\eta \mathds{1}_{\eta\ge d+x}\big) \le 2d\,e^{-x^2/32d} \,\mathds{1}_{x< 4d} +
	2xe^{-x/4} \mathds{1}_{x\ge 4d}.
	\end{equation}

First assume that $x\ge 4d$. Combining the relation
\begin{align}
	\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) &= (d+x)\mathbf P(\eta\ge d+x)+\int_x^{+\infty} \mathbf P(\eta\ge d+t)\,dt
\end{align}
with Lemma~\ref{lemme_chideux}, we get
\begin{align}
	\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big)
	&\le (d+x) e^{-x/4} + \int_x^{+\infty} e^{-t/4}\, dt\\
	&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^{+\infty}}
\end{align}
Now assume that $x<4d$. Then, using the Cauchy-Schwarz inequality and
Lemma~\ref{lemme_chideux},
\begin{align}
\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) \le \sqrt{d(d+2)} e^{-x^2/32d}.
\end{align}

\begin{align}
		\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) &= (d+x)\mathbf P(\eta\ge d+x)+\int_x^{+\infty} \mathbf P(\eta\ge d+t)\,dt
	\end{align}

\begin{align}
		\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big)
		&\le (d+x) e^{-x/4} + \int_x^{+\infty} e^{-t/4}\, dt\\
		&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^{+\infty}}
	\end{align}

\begin{align}
	\mathbf E\big(\eta\, \mathds{1}_{\eta\ge d+x}\big) \le \sqrt{d(d+2)} e^{-x^2/32d}.
	\end{align}

